"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Logo } from "@/components/primitives";
import { useI18n, LangSwitcher } from "@/components/i18n-provider";
import { ThemeToggle } from "@/components/theme-provider";
import { useAuth } from "@/components/auth-provider";

export default function RegisterPage() {
  const { t } = useI18n();
  const { register, session, loaded } = useAuth();
  const router = useRouter();

  const [companyName, setCompanyName] = useState("");
  const [loginId, setLoginId] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (loaded && session) router.replace("/dashboard");
  }, [loaded, session, router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (!companyName.trim() || !loginId.trim() || !password.trim() || !confirm.trim()) {
      setError(t.authErrRequired);
      return;
    }
    if (password !== confirm) {
      setError(t.authErrPassMatch);
      return;
    }
    setLoading(true);
    await new Promise((r) => setTimeout(r, 500));
    const result = register(companyName.trim(), loginId.trim(), password);
    setLoading(false);
    if (!result.ok) {
      setError(t.authErrExists);
      return;
    }
    router.push("/dashboard");
  };

  if (!loaded || session) return null;

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "var(--bg)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Topbar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "16px 32px",
          borderBottom: "1px solid var(--line)",
          background: "var(--surface)",
        }}
      >
        <Link href="/" style={{ textDecoration: "none", color: "inherit" }}>
          <Logo size={14} />
        </Link>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <LangSwitcher />
          <ThemeToggle />
        </div>
      </div>

      {/* Center card */}
      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "40px 24px",
        }}
      >
        <div
          style={{
            width: "100%",
            maxWidth: 420,
            background: "var(--surface)",
            border: "1px solid var(--line)",
            borderRadius: 16,
            padding: "40px 36px",
          }}
        >
          {/* Header */}
          <div style={{ textAlign: "center", marginBottom: 32 }}>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
              <Logo size={15} />
            </div>
            <div
              style={{
                fontSize: 22,
                fontWeight: 700,
                letterSpacing: "-0.02em",
                color: "var(--ink)",
                marginBottom: 8,
              }}
            >
              {t.authRegTitle}
            </div>
            <div style={{ fontSize: 13.5, color: "var(--muted)", lineHeight: 1.5 }}>
              {t.authRegSub}
            </div>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <label style={{ fontSize: 12, fontWeight: 500, color: "var(--ink-2)", letterSpacing: "0.02em" }}>
                {t.authRegCompany}
              </label>
              <input
                className="txt"
                type="text"
                autoFocus
                value={companyName}
                onChange={(e) => setCompanyName(e.target.value)}
                placeholder="Acme Corp"
              />
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <label style={{ fontSize: 12, fontWeight: 500, color: "var(--ink-2)", letterSpacing: "0.02em" }}>
                {t.authRegField}
              </label>
              <input
                className="txt"
                type="text"
                autoComplete="username"
                value={loginId}
                onChange={(e) => setLoginId(e.target.value)}
                placeholder="acme@example.com"
              />
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <label style={{ fontSize: 12, fontWeight: 500, color: "var(--ink-2)", letterSpacing: "0.02em" }}>
                {t.authRegPass}
              </label>
              <input
                className="txt"
                type="password"
                autoComplete="new-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••"
              />
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <label style={{ fontSize: 12, fontWeight: 500, color: "var(--ink-2)", letterSpacing: "0.02em" }}>
                {t.authRegConfirm}
              </label>
              <input
                className="txt"
                type="password"
                autoComplete="new-password"
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                placeholder="••••••"
              />
            </div>

            {/* Error */}
            {error && (
              <div
                style={{
                  fontSize: 12.5,
                  color: "var(--danger)",
                  background: "var(--danger-soft)",
                  border: "1px solid oklch(0.58 0.18 25 / 0.2)",
                  borderRadius: 8,
                  padding: "9px 12px",
                }}
              >
                {error}
              </div>
            )}

            <button
              type="submit"
              className="btn btn-primary"
              disabled={loading}
              style={{ width: "100%", marginTop: 6, padding: "12px 0", fontSize: 14 }}
            >
              {loading ? (
                <span className="spinner" style={{ width: 16, height: 16 }} />
              ) : (
                t.authRegBtn
              )}
            </button>
          </form>

          {/* Login link */}
          <div
            style={{
              marginTop: 24,
              textAlign: "center",
              fontSize: 13,
              color: "var(--muted)",
            }}
          >
            {t.authHaveAcc}{" "}
            <Link
              href="/login"
              style={{ color: "var(--accent-ink)", fontWeight: 500, textDecoration: "none" }}
            >
              {t.authLoginLink}
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
